    apiRequest<any>('/admin/auth/verify-login-code', { method: 'POST', body: JSON.stringify({ email, verification_code }) }),
  forgotPassword: (email: string) =>
    apiRequest<any>('/admin/auth/forgot-password', { method: 'POST', body: JSON.stringify({ email }) }),
  resetPassword: (email: string, verification_code: string, new_password_hash: string) =>
    apiRequest<any>('/admin/auth/reset-password', { method: 'POST', body: JSON.stringify({ email, verification_code, new_password: new_password_hash }) }),
  changePassword: (current_password: string, new_password: string) =>
    apiRequest<any>('/admin/auth/change-password', { method: 'POST', body: JSON.stringify({ current_password, new_password }) }),
  setupTotp: () =>
    apiRequest<any>('/admin/auth/totp/setup', { method: 'POST' }),
  verifyTotp: (totp_code: string) =>
    apiRequest<any>('/admin/auth/totp/verify', { method: 'POST', body: JSON.stringify({ totp_code }) }),
  disableTotp: () =>
    apiRequest<any>('/admin/auth/totp/disable', { method: 'POST' }),
  requestActionCode: () =>
    apiRequest<any>('/admin/auth/request-action-code', { method: 'POST' }),
  getMyProfile: () =>
    apiRequest<any>('/admin/auth/me'),
  updateMyProfile: (name: string) =>
    apiRequest<any>('/admin/auth/me', { method: 'PATCH', body: JSON.stringify({ name }) }),

  listUsers: (params?: { page?: number; limit?: number; search?: string; status?: string; plan?: string; isGuest?: boolean }) => {
    const cleanParams: Record<string, string> = {};
    if (params) {
      Object.entries(params).forEach(([key, val]) => {
        if (val !== undefined && val !== null && val !== '') {
          cleanParams[key] = String(val);
        }
      });
    }
    const query = new URLSearchParams(cleanParams).toString();
    return apiRequest<any>(`/users/${query ? `?${query}` : ''}`);
  },
  getUserDetail: (userId: string) => apiRequest<any>(`/users/${userId}`),
  updateUserStatus: (userId: string, status: string) =>
    apiRequest<any>(`/users/${userId}/status`, { method: 'PATCH', body: JSON.stringify({ status }) }),
  updateUserPlan: (userId: string, plan: string) =>
    apiRequest<any>(`/users/${userId}/plan`, { method: 'PATCH', body: JSON.stringify({ plan }) }),
  updateUserQuota: (userId: string, daily_limit: number) =>
    apiRequest<any>(`/users/${userId}/quota`, { method: 'PATCH', body: JSON.stringify({ daily_limit }) }),
  applyUserOverride: (userId: string, overrideData: { plan?: string; daily_limit?: number; status?: string }) =>
    apiRequest<any>(`/users/${userId}/override`, { method: 'POST', body: JSON.stringify(overrideData) }),

  // --- 3. RBAC & Staff Management ---
  getRoles: () => apiRequest<any[]>('/admin/roles'),
  createRole: (roleData: { name: string; description?: string; permissions: string[] }) =>
    apiRequest<any>('/admin/roles', { method: 'POST', body: JSON.stringify(roleData) }),
  updateRole: (roleId: string, roleData: { name?: string; description?: string; permissions?: string[] }) =>
    apiRequest<any>(`/admin/roles/${roleId}`, { method: 'PATCH', body: JSON.stringify(roleData) }),
  deleteRole: (roleId: string) =>
    apiRequest<any>(`/admin/roles/${roleId}`, { method: 'DELETE' }),
  getPermissions: () => apiRequest<any[]>('/admin/permissions'),
