  getRateLimitLogs: (limit?: number) => apiRequest<any[]>(`/admin/security/rate-limits${limit ? `?limit=${limit}` : ''}`),
  getBotDetectionLogs: () => apiRequest<any[]>('/admin/security/bot-logs'),
