    apiRequest<any>(`/admin/users/${userId}/quota-override`, { method: 'DELETE' }),
  getCoupons: () => apiRequest<{ data: any[] }>('/admin/coupons'),
  createCoupon: (couponData: { code: string; discount_type: 'percent' | 'fixed'; value: number; expires_at: string; usage_limit?: number }) =>
    apiRequest<{ data: any }>('/admin/coupons', { method: 'POST', body: JSON.stringify(couponData) }),
  archiveCoupon: (couponId: string) =>
    apiRequest<{ data: any }>(`/admin/coupons/${couponId}/archive`, { method: 'POST' }),

  getTrials: () => apiRequest<{ data: any[] }>('/admin/trials'),
  startTrial: (userId: string, plan: string, days: number) =>
    apiRequest<{ data: any }>('/admin/trials', { method: 'POST', body: JSON.stringify({ user_id: userId, plan, days }) }),
  extendTrial: (trialId: string, days: number) =>
    apiRequest<{ data: any }>(`/admin/trials/${trialId}/extend`, { method: 'PATCH', body: JSON.stringify({ days }) }),
  endTrial: (trialId: string) =>
    apiRequest<{ data: any }>(`/admin/trials/${trialId}/end`, { method: 'POST' }),
  getPlanPerformance: () => apiRequest<{ data: Array<{ code: string; name: string; signups: number; conversions: number }> }>('/admin/plans/performance'),

  getAbTests: () => apiRequest<{ configured: boolean; message?: string; error?: string; experiments: any[] }>('/admin/promotions/ab-tests'),
  getReferrals: (status?: string) => apiRequest<{ data: any[] }>(`/admin/promotions/referrals${status ? `?status=${status}` : ''}`),
  createReferral: (referrerUserId: string, referredEmail: string, code: string) =>
    apiRequest<{ data: any }>('/admin/promotions/referrals', { method: 'POST', body: JSON.stringify({ referrer_user_id: referrerUserId, referred_email: referredEmail, code }) }),
  convertReferral: (referralId: string) =>
    apiRequest<{ referral: any; warnings: string[] }>(`/admin/promotions/referrals/${referralId}/convert`, { method: 'POST' }),

  // --- 5. Subscriptions & Billing (live from Payment Service Prisma DB) ---
  getSubscriptions: (params?: { status?: string; limit?: number; offset?: number }) => {
    const q = params ? new URLSearchParams(
      Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined && v !== null && v !== '').map(([k, v]) => [k, String(v)]))
    ).toString() : '';
    return apiRequest<{ status: string; data: any[]; total: number }>(`/admin/subscriptions${q ? `?${q}` : ''}`);
  },
  getSubscriptionStats: () =>
    apiRequest<{ status: string; total: number; active: number; cancelled: number; past_due: number }>('/admin/subscriptions/stats'),
  getInvoices: (params?: { status?: string; limit?: number; offset?: number }) => {
    const q = params ? new URLSearchParams(
      Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined && v !== null && v !== '').map(([k, v]) => [k, String(v)]))
    ).toString() : '';
    return apiRequest<{ status: string; data: any[]; total: number }>(`/admin/invoices${q ? `?${q}` : ''}`);
  },
  getPaymentServicePlans: () =>
    apiRequest<{ status: string; data: any[] }>('/admin/payment/plans'),

  // --- 5. Automation & Workflow Engine ---
