  createAutomationRule: (ruleData: any) =>
    apiRequest<any>('/admin/automation/rules', { method: 'POST', body: JSON.stringify(ruleData) }),
  updateAutomationRule: (ruleId: string, ruleData: any) =>
    apiRequest<any>(`/admin/automation/rules/${ruleId}`, { method: 'PATCH', body: JSON.stringify(ruleData) }),
  deleteAutomationRule: (ruleId: string) =>
    apiRequest<any>(`/admin/automation/rules/${ruleId}`, { method: 'DELETE' }),
  dryRunAutomationRule: (ruleId: string, testPayload: any) =>
    apiRequest<any>(`/admin/automation/rules/${ruleId}/dry-run`, { method: 'POST', body: JSON.stringify({ payload: testPayload }) }),
  dryRunAutomation: (testPayload: any) =>
    apiRequest<any>('/admin/automation/dry-run', { method: 'POST', body: JSON.stringify({ payload: testPayload }) }),
  emitDomainEvent: (trigger_event: string, payload: any) =>
    apiRequest<any>('/admin/automation/events/emit', { method: 'POST', body: JSON.stringify({ trigger_event, payload }) }),
  getAutomationExecutionLogs: () =>
    apiRequest<any[]>('/admin/automation/execution-logs'),

  // --- Notifications & Server Settings ---
  getNotificationEmailLogs: (params?: { status?: string; type?: string; limit?: number }) => {
    const q = params ? new URLSearchParams(
      Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined && v !== null && v !== '').map(([k, v]) => [k, String(v)]))
    ).toString() : '';
    return apiRequest<any[]>(`/admin/notifications/email-logs${q ? `?${q}` : ''}`);
