  getFailedNotifications: () => apiRequest<any[]>('/admin/notifications/failed'),
  getNotificationHistory: () => apiRequest<any[]>('/admin/notifications/history'),
  getNotificationStatusOverview: () => apiRequest<any>('/admin/notifications/status'),
  getAnnouncements: () => apiRequest<any[]>('/admin/notifications/announcements'),
  createAnnouncement: (title: string, message: string, severity?: string) =>
    apiRequest<any>('/admin/notifications/announcements', { method: 'POST', body: JSON.stringify({ title, message, severity }) }),
  updateAnnouncement: (announcementId: string, updates: { title?: string; message?: string; severity?: string; is_active?: boolean }) =>
    apiRequest<any>(`/admin/notifications/announcements/${announcementId}`, { method: 'PATCH', body: JSON.stringify(updates) }),
  deleteAnnouncement: (announcementId: string) =>
    apiRequest<any>(`/admin/notifications/announcements/${announcementId}`, { method: 'DELETE' }),
  getNotificationTemplates: () => apiRequest<any[]>('/admin/notifications/templates'),
  createNotificationTemplate: (templateData: { name: string; subject: string; body_html: string; channel?: string; is_active?: boolean; type?: string }) =>
    apiRequest<any>('/admin/notifications/templates', { method: 'POST', body: JSON.stringify(templateData) }),
  updateNotificationTemplate: (templateId: string, templateData: any) =>
    apiRequest<any>(`/admin/notifications/templates/${templateId}`, { method: 'PUT', body: JSON.stringify(templateData) }),
  deleteNotificationTemplate: (templateId: string) =>
