  getNotificationServerSettings: () => apiRequest<any>('/admin/notifications/settings'),
  updateNotificationServerSettings: (settingsData: any) =>
    apiRequest<any>('/admin/notifications/settings', { method: 'PUT', body: JSON.stringify(settingsData) }),

