  getGenerationsAnalytics: () => apiRequest<any>('/admin/analytics/generations'),
  getDetailedGenerationsAnalytics: () => apiRequest<any>('/admin/analytics/generations/detailed'),
  getUsersAnalytics: () => apiRequest<any>('/admin/analytics/users'),
  getTrafficAnalytics: (fromDate?: string, toDate?: string) => {
    const params = new URLSearchParams();
    if (fromDate) params.set('from_date', fromDate);
    if (toDate) params.set('to_date', toDate);
    const qs = params.toString();
    return apiRequest<any>(`/admin/analytics/traffic${qs ? `?${qs}` : ''}`);
