  getPageDurationAnalytics: (days?: number) =>
    apiRequest<any>(`/admin/analytics/page-duration${days ? `?days=${days}` : ''}`),
  getPosthogConfig: () => apiRequest<any>('/admin/analytics/posthog/config'),
  trackPosthogEvent: (event_name: string, properties?: any) =>
    apiRequest<any>('/admin/analytics/events', { method: 'POST', body: JSON.stringify({ event_name, properties }) }),

