    const q = params ? new URLSearchParams(Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined && v !== null && (v as any) !== '').map(([k, v]) => [k, String(v)]))).toString() : '';
    return apiRequest<{ status: string; data: any[]; total: number }>(`/admin/failed-payments${q ? `?${q}` : ''}`);
  },
  getPaymentRefunds: (params?: { limit?: number; offset?: number }) => {
    const q = params ? new URLSearchParams(Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined && v !== null && (v as any) !== '').map(([k, v]) => [k, String(v)]))).toString() : '';
    return apiRequest<{ status: string; data: any[]; total: number; total_refunded_amount: number }>(`/admin/refunds${q ? `?${q}` : ''}`);
  },
};

