import React, { useEffect, useMemo, useRef, useState } from 'react';
import { ChevronDown, Search } from 'lucide-react';
import { FONT_CATEGORIES, loadGoogleFont } from '../../utils/googleFonts';

interface FontFacePickerProps {
  label?: string;
  value: string;
  onChange: (family: string) => void;
}

// Searchable font-face combobox for admin's branding settings — replaces a
// bare free-text "Primary Font Family" input (which had no real values to
// reference and blocked Publish with a native "Please fill out this field"
// popup whenever it was empty) with a real, browsable list of actual fonts.
// Mirrors user-frontend's builder FontFacePicker, restyled to admin's
// gray/purple Input theme.
const FontFacePicker: React.FC<FontFacePickerProps> = ({ label = 'Font face', value, onChange }) => {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const rootRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!open) return;
    const handlePointerDown = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('mousedown', handlePointerDown);
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('mousedown', handlePointerDown);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [open]);

  useEffect(() => {
    if (open) {
      setQuery('');
      requestAnimationFrame(() => searchRef.current?.focus());
    }
  }, [open]);

  // Preview the already-saved font (if any) as soon as this control mounts,
  // not just once the admin opens the dropdown and picks something new.
  useEffect(() => {
    if (value) loadGoogleFont(value);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const filteredCategories = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return FONT_CATEGORIES;
    return FONT_CATEGORIES
      .map((cat) => ({ ...cat, fonts: cat.fonts.filter((f) => f.family.toLowerCase().includes(q)) }))
      .filter((cat) => cat.fonts.length > 0);
  }, [query]);

  const handlePick = (family: string) => {
    loadGoogleFont(family);
    onChange(family);
    setOpen(false);
  };

  return (
    <div className="w-full text-left" ref={rootRef}>
      {label && (
        <label className="block text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase tracking-wider mb-1.5">
          {label}
        </label>
      )}
      <div className="relative">
        <button
          type="button"
          onClick={() => setOpen((o) => !o)}
          className="w-full flex items-center justify-between gap-2 px-4 py-2.5 text-xs bg-white dark:bg-white/5 text-gray-900 dark:text-white border border-gray-200 dark:border-white/10 rounded-md focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 transition-all"
          style={{ fontFamily: value || undefined }}
        >
          <span className="truncate">{value || 'Select a font…'}</span>
          <ChevronDown size={14} className="flex-shrink-0 text-gray-400" />
        </button>

        {open && (
          <div className="absolute z-[100] mt-1 left-0 right-0 bg-white dark:bg-gray-900 border border-gray-200 dark:border-white/10 rounded-md shadow-2xl overflow-hidden">
            <div className="relative border-b border-gray-200 dark:border-white/10">
              <Search size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
              <input
                ref={searchRef}
                type="text"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Search fonts…"
                className="w-full bg-transparent pl-7 pr-3 py-2 text-xs text-gray-900 dark:text-white placeholder:text-gray-400 outline-none"
              />
            </div>
            <div className="max-h-56 overflow-y-auto py-1">
              {filteredCategories.length === 0 && (
                <p className="px-3 py-2 text-xs text-gray-500 dark:text-gray-400">No fonts match "{query}"</p>
              )}
              {filteredCategories.map((cat) => (
                <div key={cat.label}>
                  <div className="px-3 pt-2 pb-1 text-[9px] font-bold uppercase tracking-wide text-gray-500 dark:text-gray-400 sticky top-0 bg-white dark:bg-gray-900">
                    {cat.label}
                  </div>
                  {cat.fonts.map((f) => (
                    <button
                      key={f.family}
                      type="button"
                      onClick={() => handlePick(f.family)}
                      style={{ fontFamily: f.family }}
                      className={`w-full text-left px-3 py-1.5 text-xs truncate transition-colors hover:bg-gray-50 dark:hover:bg-white/5 ${
                        f.family === value ? 'text-purple-600 dark:text-purple-400 font-semibold' : 'text-gray-900 dark:text-white'
                      }`}
                    >
                      {f.family}
                    </button>
                  ))}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default FontFacePicker;

import React, { useState, useEffect, useMemo } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

// Shared client-side pagination — every table that adopts it gets the same
// page-size, page-clamping, and slicing behavior instead of reimplementing it.
export function usePagination<T>(items: T[], pageSize = 8) {
  const [page, setPage] = useState(1);
  const totalPages = Math.max(1, Math.ceil(items.length / pageSize));

  useEffect(() => {
    if (page > totalPages) setPage(1);
  }, [totalPages, page]);

  const paged = useMemo(
    () => items.slice((page - 1) * pageSize, page * pageSize),
    [items, page, pageSize]
  );

  return { page, setPage, totalPages, paged, pageSize, totalItems: items.length };
}

interface PaginationProps {
  page: number;
  totalPages: number;
  totalItems: number;
  pageSize: number;
  onChange: (page: number) => void;
}

const Pagination: React.FC<PaginationProps> = ({ page, totalPages, totalItems, pageSize, onChange }) => {
  if (totalItems === 0) return null;

  const start = (page - 1) * pageSize + 1;
  const end = Math.min(page * pageSize, totalItems);

  return (
    <div className="flex items-center justify-between pt-4 mt-2 border-t border-gray-200/60 dark:border-white/10 text-[11px] text-gray-500 dark:text-gray-400">
      <span>
        Showing <span className="font-semibold text-gray-900 dark:text-white">{start}-{end}</span> of{' '}
        <span className="font-semibold text-gray-900 dark:text-white">{totalItems}</span>
      </span>
      <div className="flex items-center gap-1">
        <button
          onClick={() => onChange(Math.max(1, page - 1))}
          disabled={page <= 1}
          className="p-1.5 rounded-full hover:bg-gray-100 dark:hover:bg-white/10 disabled:opacity-30 disabled:pointer-events-none transition-colors"
          aria-label="Previous page"
        >
          <ChevronLeft size={14} />
        </button>
        <span className="px-2 font-semibold text-gray-900 dark:text-white">
          {page} / {totalPages}
        </span>
        <button
          onClick={() => onChange(Math.min(totalPages, page + 1))}
          disabled={page >= totalPages}
          className="p-1.5 rounded-full hover:bg-gray-100 dark:hover:bg-white/10 disabled:opacity-30 disabled:pointer-events-none transition-colors"
          aria-label="Next page"
        >
          <ChevronRight size={14} />
        </button>
      </div>
    </div>
  );
};

export default Pagination;

import React from 'react';
import { ArrowUp, ArrowDown, ArrowUpDown } from 'lucide-react';

export interface SortState<K extends string> {
  key: K;
  direction: 'asc' | 'desc';
}

interface SortableHeaderProps<K extends string> {
  label: string;
  sortKey: K;
  sort: SortState<K> | null;
  onSort: (key: K) => void;
  align?: 'left' | 'right';
  className?: string;
}

function SortableHeader<K extends string>({ label, sortKey, sort, onSort, align = 'left', className = '' }: SortableHeaderProps<K>) {
  const isActive = sort?.key === sortKey;
  const Icon = isActive ? (sort!.direction === 'asc' ? ArrowUp : ArrowDown) : ArrowUpDown;

  return (
    <th className={`pb-3 font-bold ${align === 'right' ? 'text-right' : 'text-left'} ${className}`}>
      <button
        onClick={() => onSort(sortKey)}
        className={`inline-flex items-center gap-1 hover:text-gray-900 dark:hover:text-white transition-colors ${
          align === 'right' ? 'flex-row-reverse' : ''
        } ${isActive ? 'text-gray-900 dark:text-white' : ''}`}
      >
        {label}
        <Icon size={11} className={isActive ? 'text-purple-500' : 'text-gray-400 dark:text-gray-600'} />
      </button>
    </th>
  );
}

export default SortableHeader;

// Generic comparator used alongside SortableHeader — keeps the "click header
// to sort" behavior identical everywhere it's used instead of each table
// hand-rolling its own compare function.
export function sortRows<T>(rows: T[], sort: SortState<string> | null, getValue: (row: T, key: string) => any): T[] {
  if (!sort) return rows;
  const sorted = [...rows].sort((a, b) => {
    const av = getValue(a, sort.key);
    const bv = getValue(b, sort.key);
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    if (typeof av === 'number' && typeof bv === 'number') return av - bv;
    return String(av).localeCompare(String(bv));
  });
  return sort.direction === 'asc' ? sorted : sorted.reverse();
}

export function useSortToggle<K extends string>() {
  const [sort, setSort] = React.useState<SortState<K> | null>(null);
  const toggleSort = (key: K) => {
    setSort((prev) => {
      if (!prev || prev.key !== key) return { key, direction: 'asc' };
      if (prev.direction === 'asc') return { key, direction: 'desc' };
      return null;
    });
  };
  return { sort, toggleSort };
}

