// ─── Type definitions ──────────────────────────────────────────────────────

interface ConditionRow {
  field: string;
  operator: string;
  value: string;
}

interface ActionRow {
  action_type: string;
  target: string;
  payload: string; // JSON string
}

interface AutomationRule {
  id: string;
  name: string;
  description?: string;
  trigger_event: string;
  conditions: ConditionRow[];
  actions: ActionRow[];
  status: 'active' | 'disabled';
  retry_limit: number;
  created_at?: string;
  updated_at?: string;
  rawRule?: any;
}

interface ExecutionLog {
  id: string;
  rule_id: string;
  rule_name: string;
  trigger_event: string;
  status: 'success' | 'failed' | 'retrying' | 'dead_letter';
  conditions_passed: boolean;
  retry_count: number;
  error_message?: string;
  created_at: string;
  action_results?: any[];
  payload?: any;
}

// ─── Constants ─────────────────────────────────────────────────────────────

const TRIGGER_EVENTS = [
  'quota.warning',
  'quota.exhausted',
  'payment.failed',
  'payment.succeeded',
  'user.registered',
  'user.suspended',
  'subscription.activated',
  'subscription.cancelled',
  'subscription.past_due',
  'document.generated',
];

const OPERATORS = [
  { value: 'equals', label: '= equals' },
  { value: 'not_equals', label: '≠ not equals' },
  { value: 'greater_than', label: '> greater than' },
  { value: 'less_than', label: '< less than' },
  { value: 'greater_than_or_equal', label: '≥ greater than or equal' },
  { value: 'less_than_or_equal', label: '≤ less than or equal' },
  { value: 'contains', label: '∋ contains' },
  { value: 'in', label: 'in (list)' },
];

const ACTION_TYPES = [
  { value: 'send_email', label: 'Send Email' },
  { value: 'grant_quota_override', label: 'Grant Quota Override' },
  { value: 'block_ip', label: 'Block IP Address' },
  { value: 'webhook', label: 'POST Webhook' },
];

// ─── Helpers ───────────────────────────────────────────────────────────────

function statusBadgeVariant(s: string): 'success' | 'danger' | 'warning' | 'secondary' {
  if (s === 'success') return 'success';
  if (s === 'dead_letter' || s === 'failed') return 'danger';
  if (s === 'retrying') return 'warning';
  return 'secondary';
}

function statusLabel(s: string): string {
  if (s === 'dead_letter') return 'Dead Letter';
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function parseConditionsFromRaw(raw: any[]): ConditionRow[] {
  if (!Array.isArray(raw)) return [];
  return raw.map((c) => ({ field: c.field || '', operator: c.operator || 'equals', value: String(c.value ?? '') }));
}

function parseActionsFromRaw(raw: any[]): ActionRow[] {
  if (!Array.isArray(raw)) return [];
  return raw.map((a) => ({
    action_type: a.action_type || 'send_email',
    target: a.target || '',
    payload: JSON.stringify(a.payload || {}, null, 2),
  }));
}

function ruleFromApiResponse(r: any): AutomationRule {
  return {
    id: r.id,
    name: r.name,
    description: r.description,
    trigger_event: r.trigger_event || '',
    conditions: parseConditionsFromRaw(r.conditions || []),
    actions: parseActionsFromRaw(r.actions || []),
    status: r.status === 'active' || r.is_active ? 'active' : 'disabled',
    retry_limit: r.retry_limit ?? 3,
    created_at: r.created_at,
    updated_at: r.updated_at,
    rawRule: r,
  };
}

