import React, { useState, useEffect } from 'react';
import Card from '../../components/ui/Card';
import Badge from '../../components/ui/Badge';
import Button from '../../components/ui/Button';
import { FileText, Code2, Eye, RefreshCw, UploadCloud, X } from 'lucide-react';
import { 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, 
  Tooltip as ChartTooltip
} from 'recharts';
import { adminApiClient } from '../../api/adminApiClient';
import { toast, getErrorMessage } from '../../store/toastStore';

interface DocumentsViewProps {
  activeSubItem: string;
}

const DocumentsView: React.FC<DocumentsViewProps> = ({ activeSubItem }) => {
  const [templates, setTemplates] = useState<any[]>([
    { id: 'tpl_invoice_v2', name: 'Standard Invoice Template', type: 'Invoice', version: 'v2.1', status: 'Published', lastUpdated: '2026-06-14', author: 'Super Admin', html_content: '<div class="invoice-box"><h1>Invoice #{{ invoice_number }}</h1><p>Client: {{ client_name }}</p></div>' },
    { id: 'tpl_quotation_v1', name: 'Modern Quotation Template', type: 'Quotation', version: 'v1.8', status: 'Published', lastUpdated: '2026-06-10', author: 'Super Admin', html_content: '<div class="quote-box"><h1>Quotation #{{ quote_id }}</h1><p>Total: LKR {{ total_amount }}</p></div>' },
    { id: 'tpl_proposal_v3', name: 'Agency Proposal Template', type: 'Proposal', version: 'v3.0-draft', status: 'Draft', lastUpdated: '2026-06-15', author: 'Design Team', html_content: '<div class="proposal-box"><h1>Proposal for {{ company_name }}</h1></div>' }
  ]);

  const [isLoadingTemplates, setIsLoadingTemplates] = useState(false);
  const [previewTemplate, setPreviewTemplate] = useState<any | null>(null);

  const loadTemplatesFromApi = async () => {
    setIsLoadingTemplates(true);
    try {
      const data = await adminApiClient.getTemplates();
      if (Array.isArray(data) && data.length > 0) {
        setTemplates(data);
      }
    } catch (err) {
      console.warn('Using fallback templates list:', err);
    } finally {
      setIsLoadingTemplates(false);
    }
  };

  useEffect(() => {
    loadTemplatesFromApi();
  }, []);

  // Both populated from GET /admin/analytics/generations/detailed, which
  // reads the Document Service's real `documents` table directly (admin-api
  // and Document Service share the same Postgres database) — real document
  // type/template/status/timestamp per row. There is no byte-size column
  // anywhere in that table (PDFs are written to Supabase Storage by key,
  // and nothing measures/stores their size), so this table never shows a
  // fabricated file size the way it used to.
  const [docLogs, setDocLogs] = useState<any[]>([]);
  const [docBreakdown, setDocBreakdown] = useState<{ name: string; value: number }[]>([]);
  const [isLoadingDocLogs, setIsLoadingDocLogs] = useState(false);

  const loadDocLogs = async () => {
    setIsLoadingDocLogs(true);
    try {
      const data = await adminApiClient.getDetailedGenerationsAnalytics();
      const recent = Array.isArray(data?.recent_generations) ? data.recent_generations : [];
      setDocLogs(recent.map((row: any) => ({
        id: row.id,
        user: row.user,
        type: String(row.type || 'Unknown').toUpperCase(),
        template: row.template,
        status: row.status,
        date: row.date,
      })));

      const byType = Array.isArray(data?.by_type) ? data.by_type : [];
      setDocBreakdown(byType.map((row: any) => ({ name: row.name, value: row.count })));
    } catch (err) {
      console.warn('Doc logs fetch warning:', err);
    } finally {
      setIsLoadingDocLogs(false);
    }
  };

  useEffect(() => {
    loadDocLogs();
  }, []);

  const handlePublishTemplate = async (templateId: string) => {
    try {
      await adminApiClient.publishTemplate(templateId);
      setTemplates(templates.map(t => t.id === templateId ? { ...t, status: 'Published' } : t));
      toast.success('Template Published', `${templateId} is now live on the document rendering cluster.`);
    } catch (err: any) {
      setTemplates(templates.map(t => t.id === templateId ? { ...t, status: 'Published' } : t));
      toast.error('Publish Not Confirmed by Server', `${getErrorMessage(err)} — status updated locally only.`);
    }
  };

  if (activeSubItem === 'doc_templates' || activeSubItem === 'doc_version_registry') {
    return (
      <div className="space-y-6 text-left">
        <Card className="">
          <div className="flex items-center justify-between mb-4 pb-3 border-b border-gray-200/60 dark:border-white/10">
            <div>
              <h3 className="text-xs font-bold uppercase tracking-wider text-gray-900 dark:text-white flex items-center gap-2">
                <FileText size={16} className="text-purple-600 dark:text-purple-400" />
                Document Template Version Registry (FR-ADM-01..03)
              </h3>
              <p className="text-[10px] text-gray-500 dark:text-gray-400">Jinja2 HTML template source versioning & publish controls</p>
            </div>
            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" onClick={loadTemplatesFromApi} disabled={isLoadingTemplates} className="flex items-center gap-1">
                <RefreshCw size={12} className={isLoadingTemplates ? 'animate-spin' : ''} /> Reload Templates
              </Button>
              <Badge variant="primary">{templates.length} Templates Registered</Badge>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-xs text-left">
              <thead>
                <tr className="border-b border-gray-200/60 dark:border-white/10 text-gray-500 dark:text-gray-400 uppercase tracking-wider text-[10px]">
                  <th className="pb-3 font-bold">Template ID</th>
                  <th className="pb-3 font-bold">Template Name</th>
                  <th className="pb-3 font-bold">Document Type</th>
                  <th className="pb-3 font-bold">Active Version</th>
                  <th className="pb-3 font-bold">Last Modified</th>
                  <th className="pb-3 font-bold">Status</th>
                  <th className="pb-3 text-right font-bold">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200/40 dark:divide-white/5">
                {templates.map((t) => (
                  <tr key={t.id} className="hover:bg-purple-500/5 transition-colors">
                    <td className="py-3 font-mono text-gray-500 dark:text-gray-400">{t.id}</td>
                    <td className="py-3 text-gray-900 dark:text-white font-bold">{t.name}</td>
                    <td className="py-3 font-semibold text-purple-600 dark:text-purple-400">{t.type}</td>
                    <td className="py-3 font-mono text-gray-500 dark:text-gray-400 font-bold">{t.version}</td>
                    <td className="py-3 text-gray-500 dark:text-gray-400">{t.lastUpdated}</td>
                    <td className="py-3">
                      <Badge variant={t.status === 'Published' ? 'success' : 'warning'}>{t.status}</Badge>
                    </td>
                    <td className="py-3 text-right flex items-center justify-end gap-2">
                      <Button variant="outline" size="sm" onClick={() => setPreviewTemplate(t)}>
                        <Eye size={12} /> Preview Source
                      </Button>
                      {t.status !== 'Published' && (
                        <Button variant="violet" size="sm" className="flex items-center gap-1.5" onClick={() => handlePublishTemplate(t.id)}>
                          <UploadCloud size={12} /> Publish Version
                        </Button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>

        {/* Source Preview Modal */}
        {previewTemplate && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 text-left">
            <Card className="max-w-2xl w-full p-6 space-y-4 border-gray-200 dark:border-white/10 shadow-2xl relative">
              <div className="pb-3 border-b border-gray-200/60 dark:border-white/10 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Code2 size={18} className="text-purple-600 dark:text-purple-400" />
                  <h3 className="text-sm font-bold text-gray-900 dark:text-white">
                    Jinja2 HTML Template Source: {previewTemplate.name} ({previewTemplate.version})
                  </h3>
                </div>
                <button onClick={() => setPreviewTemplate(null)} className="text-gray-400 hover:text-gray-600 dark:hover:text-white"><X size={16} /></button>
              </div>

              <div className="space-y-2">
                <label className="block text-[10px] text-gray-500 uppercase font-bold tracking-wider">Raw Template Source Code</label>
                <pre className="p-4 bg-neutral-950 text-emerald-400 font-mono text-xs rounded-md overflow-x-auto border border-neutral-800 max-h-80">
                  {previewTemplate.html_content || `<!-- DocCraft Jinja2 Template: ${previewTemplate.name} -->\n<div class="document-container">\n  <h1>{{ document_title }}</h1>\n  <p>Issued by {{ company_name }}</p>\n</div>`}
                </pre>
              </div>

              <div className="pt-2 flex justify-end gap-2 border-t border-gray-200/60 dark:border-white/10">
                <Button variant="outline" size="sm" className="flex items-center gap-1.5" onClick={() => setPreviewTemplate(null)}><X size={12} /> Close Preview</Button>
              </div>
            </Card>
          </div>
        )}
      </div>
    );
  }

  if (activeSubItem === 'doc_all' || activeSubItem === 'doc_breakdown' || activeSubItem === 'doc_links' || activeSubItem === 'doc_history' || activeSubItem === 'doc_shared_analytics') {
    return (
      <div className="space-y-6 text-left">
        <Card className="">
          <div className="flex items-center justify-between mb-4 pb-3 border-b border-gray-200/60 dark:border-white/10">
            <h3 className="text-xs font-bold uppercase tracking-wider text-gray-900 dark:text-white">
              Generated Document Logs
            </h3>
            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" onClick={loadDocLogs} disabled={isLoadingDocLogs} className="flex items-center gap-1">
                <RefreshCw size={12} className={isLoadingDocLogs ? 'animate-spin' : ''} /> Reload
              </Button>
              <Badge variant="primary">{docLogs.length} Recent Logs</Badge>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-xs text-left">
              <thead>
                <tr className="border-b border-gray-200/60 dark:border-white/10 text-gray-500 dark:text-gray-400 uppercase tracking-wider text-[10px]">
                  <th className="pb-3 font-bold">Document ID</th>
                  <th className="pb-3 font-bold">Generating User</th>
                  <th className="pb-3 font-bold">Document Type</th>
                  <th className="pb-3 font-bold">Template Used</th>
                  <th className="pb-3 font-bold">Status</th>
                  <th className="pb-3 text-right font-bold">Timestamp</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200/40 dark:divide-white/5">
                {docLogs.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="py-8 text-center text-appTextSecondary">
                      {isLoadingDocLogs ? 'Loading…' : 'No documents generated yet.'}
                    </td>
                  </tr>
                ) : (
                  docLogs.map((doc) => (
                    <tr key={doc.id} className="hover:bg-purple-500/5 transition-colors">
                      <td className="py-3 font-mono text-gray-500 dark:text-gray-400">{doc.id}</td>
                      <td className="py-3 text-gray-900 dark:text-white font-bold">{doc.user}</td>
                      <td className="py-3 text-purple-600 dark:text-purple-400 font-bold">{doc.type}</td>
                      <td className="py-3 font-mono text-gray-500 dark:text-gray-400">{doc.template}</td>
                      <td className="py-3">
                        <Badge variant={doc.status === 'success' ? 'success' : doc.status === 'failed' ? 'danger' : 'secondary'}>
                          {doc.status}
                        </Badge>
                      </td>
                      <td className="py-3 text-right text-gray-500 dark:text-gray-400">{doc.date}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>

        <Card className="h-[280px] flex flex-col">
          <h3 className="text-xs font-bold uppercase tracking-wider text-gray-900 dark:text-white mb-4">
            Document Generation Breakdown by Category
          </h3>
          <div className="flex-1 w-full text-xs">
            {docBreakdown.length === 0 ? (
              <div className="h-full flex items-center justify-center text-appTextSecondary">
                {isLoadingDocLogs ? 'Loading…' : 'No successful generations yet.'}
              </div>
            ) : (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={docBreakdown}>
                  <XAxis dataKey="name" stroke="#97959E" fontSize={10} />
                  <YAxis stroke="#97959E" fontSize={10} />
                  <ChartTooltip />
                  <Bar dataKey="value" fill="#7367F0" name="Generations" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </div>
        </Card>
      </div>
    );
  }

  return null;
};

export default DocumentsView;

import React, { useState, useEffect } from 'react';
import Card from '../../components/ui/Card';
import Badge from '../../components/ui/Badge';
import { FileWarning, Search } from 'lucide-react';
import {
  ResponsiveContainer, BarChart, Bar, Cell, XAxis, YAxis,
  Tooltip as ChartTooltip, Legend
} from 'recharts';
import { adminApiClient } from '../../api/adminApiClient';
import { toast } from '../../store/toastStore';

interface GenerationsViewProps {
  activeSubItem: string;
}

// ── Real today/yesterday using current local date ──────────────────────────
const todayISO   = new Date().toISOString().substring(0, 10);
const ydDate     = new Date(Date.now() - 86_400_000);
const yesterdayISO = ydDate.toISOString().substring(0, 10);
const todayLabel     = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric' });
const yesterdayLabel = ydDate.toLocaleDateString('en-US', { month: 'long', day: 'numeric' });

const GenerationsView: React.FC<GenerationsViewProps> = ({ activeSubItem }) => {
  // ── Filter state ──────────────────────────────────────────────────────────
  const [searchTerm, setSearchTerm] = useState('');
  const [dateFilter, setDateFilter] = useState('all');
  const [startDate, setStartDate]   = useState('');
  const [endDate,   setEndDate]     = useState('');

  // ── Live data state — real, including a genuine empty/zero state ─────────
  const [docTypeStats,      setDocTypeStats]      = useState<any[]>([]);
  const [monthlyGens,       setMonthlyGens]       = useState<any[]>([]);
  const [topUsers,          setTopUsers]          = useState<any[]>([]);
  const [failedGenerations, setFailedGenerations] = useState<any[]>([]);
  const [dropOffPoints,     setDropOffPoints]     = useState<any[]>([]);
  const [freeTierTotal,     setFreeTierTotal]     = useState<number>(0);
  const [proTierTotal,      setProTierTotal]      = useState<number>(0);
  const [loading,           setLoading]           = useState(true);

  useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        const data = await adminApiClient.getDetailedGenerationsAnalytics();
        setDocTypeStats(Array.isArray(data?.by_type) ? data.by_type : []);
        setMonthlyGens(Array.isArray(data?.monthly_trend) ? data.monthly_trend : []);
        setTopUsers(Array.isArray(data?.top_users) ? data.top_users : []);
        setFailedGenerations(Array.isArray(data?.failed_generations) ? data.failed_generations : []);
        setDropOffPoints(Array.isArray(data?.drop_off_points) ? data.drop_off_points : []);
        setFreeTierTotal(typeof data?.free_tier_total === 'number' ? data.free_tier_total : 0);
        setProTierTotal(typeof data?.pro_tier_total === 'number' ? data.pro_tier_total : 0);
      } catch (err) {
        console.warn('[GenerationsView] load error:', err);
        toast.error('Failed to Load Generation Analytics', 'Could not reach the admin API.');
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  // ── Date matcher (uses real today/yesterday) ──────────────────────────────
  const matchesDate = (itemDate: string) => {
    const d = (itemDate || '').substring(0, 10);
    if (dateFilter === 'all')       return true;
    if (dateFilter === 'today')     return d === todayISO;
    if (dateFilter === 'yesterday') return d === yesterdayISO;
    if (dateFilter === 'range') {
      if (!startDate && !endDate) return true;
      if (startDate && d < startDate) return false;
      if (endDate   && d > endDate)   return false;
      return true;
    }
    return true;
  };

  // ── Shared filter toolbar ─────────────────────────────────────────────────
  const renderFilterToolbar = (title: string, count: number) => (
    <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 pb-4 border-b border-appBorder/50 mb-4 text-left">
      <div className="flex items-center gap-2">
        <h3 className="text-xs font-bold uppercase tracking-wider text-appTextPrimary">{title}</h3>
        <Badge variant="primary">{count}</Badge>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <div className="relative">
          <Search size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-appTextSecondary/60" />
          <input
            type="text"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
            placeholder="Search…"
            className="pl-8 pr-3 py-1 bg-appBg text-[11px] text-appTextPrimary border border-appBorder rounded-md focus:outline-none focus:border-appPrimary w-40"
          />
        </div>
        <select
          value={dateFilter}
          onChange={e => setDateFilter(e.target.value)}
          className="px-2 py-1 bg-appBg text-[11px] text-appTextPrimary border border-appBorder rounded-md focus:outline-none focus:border-appPrimary"
        >
          <option value="all">All Time</option>
          <option value="today">Today ({todayLabel})</option>
          <option value="yesterday">Yesterday ({yesterdayLabel})</option>
          <option value="range">Custom Range</option>
        </select>
        {dateFilter === 'range' && (
          <div className="flex items-center gap-1">
            <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)}
              className="px-2 py-0.5 bg-appBg text-[10px] text-appTextPrimary border border-appBorder rounded-md focus:outline-none" />
            <span className="text-[10px] text-appTextSecondary">to</span>
            <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)}
              className="px-2 py-0.5 bg-appBg text-[10px] text-appTextPrimary border border-appBorder rounded-md focus:outline-none" />
          </div>
        )}
      </div>
    </div>
  );

  // ── Loading placeholder ───────────────────────────────────────────────────
  if (loading) {
    return (
      <Card>
        <p className="text-xs text-appTextSecondary animate-pulse py-6 text-center">
          Loading generation analytics…
        </p>
      </Card>
    );
  }

  // ── 1. Total generations bar chart ────────────────────────────────────────
  if (activeSubItem === 'gen_total') {
    return (
      <Card className="h-[320px] flex flex-col">
        <h3 className="text-xs font-bold uppercase tracking-wider text-appTextPrimary mb-4">
          Total Generations Trend
        </h3>
        {monthlyGens.length === 0 ? (
          <p className="text-xs text-appTextSecondary text-center my-auto">
            No generation data yet. Data will appear once users create documents.
          </p>
        ) : (
          <div className="flex-1 w-full text-xs">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={monthlyGens}>
                <XAxis dataKey="month" stroke="var(--text-secondary)" fontSize={10} />
                <YAxis stroke="var(--text-secondary)" fontSize={10} />
                <ChartTooltip />
                <Legend />
                <Bar dataKey="pro"  stackId="a" fill="#7367F0" name="Pro Generations"  />
                <Bar dataKey="free" stackId="a" fill="#97959E" name="Free Generations" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}
      </Card>
    );
  }

  // ── 2. Generations by document type ──────────────────────────────────────
  if (activeSubItem === 'gen_by_type') {
    // Compute most popular type and its share from live data
    const topType   = docTypeStats[0] ?? null;
    const totalDocs = docTypeStats.reduce((s, d) => s + (d.count || 0), 0);
    const topPct    = topType && totalDocs > 0
      ? ((topType.count / totalDocs) * 100).toFixed(1)
      : '0';

    return (
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2 h-[320px] flex flex-col">
          <h3 className="text-xs font-bold uppercase tracking-wider text-appTextPrimary mb-4">
            Generations Breakdown by Document Type
          </h3>
          {docTypeStats.length === 0 ? (
            <p className="text-xs text-appTextSecondary text-center my-auto">
              No documents generated yet.
            </p>
          ) : (
            <div className="flex-1 w-full text-xs">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={docTypeStats} layout="vertical">
                  <XAxis type="number" stroke="var(--text-secondary)" fontSize={10} />
                  <YAxis dataKey="name" type="category" stroke="var(--text-secondary)" fontSize={10} width={100} />
                  <ChartTooltip />
                  <Bar dataKey="count" radius={[0, 4, 4, 0]}>
                    {docTypeStats.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}
        </Card>

        <Card className="flex flex-col justify-between h-[320px]">
          <div>
            <h3 className="text-xs font-bold uppercase tracking-wider text-appTextPrimary mb-4">
              Most Popular Type
            </h3>
            {topType ? (
              <>
                <p className="text-2xl font-black text-appPrimary">{topType.name}</p>
                <p className="text-xs text-appTextSecondary mt-2">
                  Accounting for approximately <span className="font-bold text-appTextPrimary">{topPct}%</span> of
                  all documents created in DocCraft.
                </p>
              </>
            ) : (
              <p className="text-xs text-appTextSecondary mt-2">No data yet.</p>
            )}
          </div>
          <div className="p-3 bg-appBg border border-appBorder rounded-md text-[10px] text-appTextSecondary">
            Total document types: <span className="font-bold text-appTextPrimary">{docTypeStats.length}</span>
          </div>
        </Card>
      </div>
    );
  }

  // ── 3. Generations by user ────────────────────────────────────────────────
  if (activeSubItem === 'gen_by_user') {
    const filtered = topUsers.filter(u => {
      const match = (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                    (u.id    || '').toLowerCase().includes(searchTerm.toLowerCase());
      return match && matchesDate(u.date);
    });

    return (
      <Card>
        {renderFilterToolbar('Top Power Users (Generation Count)', filtered.length)}
        <div className="overflow-x-auto">
          {filtered.length === 0 ? (
            <p className="text-xs text-appTextSecondary text-center py-6">No user generation data found.</p>
          ) : (
            <table className="w-full text-xs text-left">
              <thead>
                <tr className="border-b border-appBorder text-appTextSecondary uppercase tracking-wider">
                  <th className="pb-3 font-bold">User ID</th>
                  <th className="pb-3 font-bold">Email Address</th>
                  <th className="pb-3 font-bold">Plan</th>
                  <th className="pb-3 text-right font-bold">Generations</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-appBorder/40">
                {filtered.map((user, idx) => (
                  <tr key={user.id ?? idx} className="hover:bg-appBg/10 transition-colors">
                    <td className="py-3 font-mono text-appTextSecondary">{user.id}</td>
                    <td className="py-3 text-appTextPrimary font-bold">{user.email}</td>
                    <td className="py-3">
                      <Badge variant={user.plan === 'pro' ? 'primary' : 'info'}>
                        {(user.plan || 'free').toUpperCase()}
                      </Badge>
                    </td>
                    <td className="py-3 text-right font-black font-mono text-appPrimary">{user.count} docs</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </Card>
    );
  }

  // ── 4. Failed generations log ─────────────────────────────────────────────
  if (activeSubItem === 'gen_failed') {
    const filtered = failedGenerations.filter(f => {
      const match = (f.user  || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                    (f.error || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                    (f.id    || '').toLowerCase().includes(searchTerm.toLowerCase());
      return match && matchesDate(f.date);
    });

    return (
      <Card>
        {renderFilterToolbar('Generation Failures Registry', filtered.length)}
        <div className="overflow-x-auto">
          {filtered.length === 0 ? (
            <p className="text-xs text-appTextSecondary text-center py-6">No failures logged — all generations succeeded.</p>
          ) : (
            <table className="w-full text-xs text-left">
              <thead>
                <tr className="border-b border-appBorder text-appTextSecondary uppercase tracking-wider">
                  <th className="pb-3 font-bold">Failure ID</th>
                  <th className="pb-3 font-bold">User</th>
                  <th className="pb-3 font-bold">Document Type</th>
                  <th className="pb-3 font-bold">Diagnostics Error</th>
                  <th className="pb-3 text-right font-bold">Timestamp</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-appBorder/40">
                {filtered.map((fail, idx) => (
                  <tr key={fail.id ?? idx} className="hover:bg-appBg/10 transition-colors">
                    <td className="py-3 font-mono text-appTextSecondary">{fail.id}</td>
                    <td className="py-3 text-appTextPrimary font-bold">{fail.user}</td>
                    <td className="py-3 font-semibold capitalize">{fail.type}</td>
                    <td className="py-3 text-appError font-mono flex items-center gap-1">
                      <FileWarning size={12} /> {fail.error}
                    </td>
                    <td className="py-3 text-right text-appTextSecondary">{fail.date}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </Card>
    );
  }

  // ── 5. Free tier / Pro tier stats ────────────────────────────────────────
  if (activeSubItem === 'gen_free_tier' || activeSubItem === 'gen_pro_tier') {
    const isPro  = activeSubItem === 'gen_pro_tier';
    const total  = isPro ? proTierTotal : freeTierTotal;

    return (
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card className="flex flex-col justify-between h-[150px]">
          <div>
            <span className="text-[10px] text-appTextSecondary uppercase font-bold tracking-wider">
              {isPro ? 'Pro Total Generations' : 'Free Total Generations'}
            </span>
            <p className="text-2xl font-black text-appTextPrimary mt-2">
              {total.toLocaleString()}
            </p>
          </div>
          <Badge variant="primary">{isPro ? 'Pro member usage' : 'Daily resetting counters'}</Badge>
        </Card>

        <Card className="flex flex-col justify-between h-[150px]">
          <div>
            <span className="text-[10px] text-appTextSecondary uppercase font-bold tracking-wider">
              {isPro ? 'Export Method' : 'Watermark Status'}
            </span>
            <p className="text-base font-bold text-appTextPrimary mt-2">
              {isPro ? 'Server-side Puppeteer' : 'Client-side overlay'}
            </p>
          </div>
          <Badge variant="success">Pixel accurate</Badge>
        </Card>

        <Card className="flex flex-col justify-between h-[150px]">
          <div>
            <span className="text-[10px] text-appTextSecondary uppercase font-bold tracking-wider">
              Share of All Generations
            </span>
            <p className="text-base font-bold text-appTextPrimary mt-2">
              {(freeTierTotal + proTierTotal) > 0
                ? `${(((isPro ? proTierTotal : freeTierTotal) / (freeTierTotal + proTierTotal)) * 100).toFixed(1)}%`
                : '—'}
            </p>
          </div>
          <Badge variant="info">{isPro ? 'Pro tier share' : 'Free tier share'}</Badge>
        </Card>
      </div>
    );
  }

  // ── 6. Chat funnel drop-off ───────────────────────────────────────────────
  if (activeSubItem === 'gen_drop_offs') {
    return (
      <Card>
        <h3 className="text-xs font-bold uppercase tracking-wider text-appTextPrimary mb-4">
          Chat Assistant Funnel &amp; Drop-off Analysis
        </h3>
        {dropOffPoints.length === 0 ? (
          <p className="text-xs text-appTextSecondary text-center py-6">
            No funnel data yet. Data appears once generation_events are recorded.
          </p>
        ) : (
          <div className="space-y-4">
            {dropOffPoints.map((p, idx) => (
              <div key={idx} className="space-y-1.5 text-left">
                <div className="flex justify-between items-baseline text-xs">
                  <span className="font-semibold">{p.step}</span>
                  <span className="text-appTextSecondary font-bold">
                    {p.count}% active{' '}
                    <span className="text-appError font-semibold">({p.rate})</span>
                  </span>
                </div>
                <div className="w-full h-2 bg-appBg border border-appBorder rounded-md overflow-hidden">
                  <div
                    className="h-full bg-appPrimary rounded-md transition-all duration-500"
                    style={{ width: `${Math.min(100, Math.max(0, p.count))}%` }}
                  />
                </div>
              </div>
            ))}
          </div>
        )}
      </Card>
    );
  }

  return null;
};

export default GenerationsView;

